//! Layout templates (C3.1): bundled page templates (generated by `scripts/gen_layout_templates.py` and embedded in the
//! engine, so no runtime paths are needed) and the user's own, kept as JSON files in a per-user folder.

use super::model::Layout;
use anyhow::{anyhow, bail, Result};
use serde::Serialize;
use std::path::Path;

/// (file name, contents) of every bundled template, in menu order.
pub const BUILTIN: [(&str, &str); 10] = [
    ("letter-landscape", include_str!("../../assets/layout_templates/letter-landscape.json")),
    ("letter-portrait", include_str!("../../assets/layout_templates/letter-portrait.json")),
    ("legal-landscape", include_str!("../../assets/layout_templates/legal-landscape.json")),
    ("legal-portrait", include_str!("../../assets/layout_templates/legal-portrait.json")),
    ("tabloid-landscape", include_str!("../../assets/layout_templates/tabloid-landscape.json")),
    ("tabloid-portrait", include_str!("../../assets/layout_templates/tabloid-portrait.json")),
    ("a4-landscape", include_str!("../../assets/layout_templates/a4-landscape.json")),
    ("a4-portrait", include_str!("../../assets/layout_templates/a4-portrait.json")),
    ("a3-landscape", include_str!("../../assets/layout_templates/a3-landscape.json")),
    ("a3-portrait", include_str!("../../assets/layout_templates/a3-portrait.json")),
];

#[derive(Debug, Clone, Serialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct TemplateInfo {
    /// "builtin:<file>" or "user:<file>".
    pub id: String,
    pub name: String,
    pub builtin: bool,
    pub width: f64,
    pub height: f64,
}

fn info(id: String, builtin: bool, l: &Layout) -> TemplateInfo {
    TemplateInfo { id, name: l.name.clone(), builtin, width: l.page.width, height: l.page.height }
}

/// A file name made from a template name: letters, digits, space, `-`, `_`; the rest becomes `_`; never empty.
pub fn file_stem(name: &str) -> String {
    let s: String = name.chars().map(|c| if c.is_alphanumeric() || matches!(c, ' ' | '-' | '_') { c } else { '_' }).collect();
    let s = s.trim().chars().take(80).collect::<String>();
    if s.is_empty() { "template".into() } else { s }
}

fn user_files(dir: &Path) -> Vec<(String, std::path::PathBuf)> {
    let mut v: Vec<(String, std::path::PathBuf)> = std::fs::read_dir(dir)
        .into_iter()
        .flatten()
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|x| x == "json"))
        .filter_map(|p| Some((p.file_stem()?.to_string_lossy().to_string(), p)))
        .collect();
    v.sort_by_key(|(n, _)| n.to_lowercase());
    v
}

/// Every template: the bundled ones, then the user's by name. A user file that doesn't parse is skipped (listed in `skipped`).
pub fn list(user_dir: &Path) -> (Vec<TemplateInfo>, Vec<String>) {
    let mut out = Vec::new();
    for (file, json) in BUILTIN {
        if let Ok(l) = Layout::from_json(json) {
            out.push(info(format!("builtin:{file}"), true, &l));
        }
    }
    let mut skipped = Vec::new();
    for (stem, path) in user_files(user_dir) {
        match std::fs::read_to_string(&path).map_err(|e| anyhow!("{e}")).and_then(|t| Layout::from_json(&t)) {
            Ok(l) => out.push(info(format!("user:{stem}"), false, &l)),
            Err(e) => skipped.push(format!("{stem}.json: {e}")),
        }
    }
    (out, skipped)
}

/// A template's layout (the caller gives it a new id and name).
pub fn load(id: &str, user_dir: &Path) -> Result<Layout> {
    if let Some(file) = id.strip_prefix("builtin:") {
        let (_, json) = BUILTIN.iter().find(|(f, _)| *f == file).ok_or_else(|| anyhow!("There is no template '{id}'"))?;
        return Layout::from_json(json);
    }
    let stem = id.strip_prefix("user:").ok_or_else(|| anyhow!("There is no template '{id}'"))?;
    if stem != file_stem(stem) {
        bail!("There is no template '{id}'");
    }
    let path = user_dir.join(format!("{stem}.json"));
    let text = std::fs::read_to_string(&path).map_err(|_| anyhow!("There is no template '{id}'"))?;
    Layout::from_json(&text)
}

/// Save a layout as a user template named `name` (same name = replaced). Returns its entry.
pub fn save(name: &str, layout: &Layout, user_dir: &Path) -> Result<TemplateInfo> {
    let name = name.trim();
    if name.is_empty() {
        bail!("A template needs a name");
    }
    layout.validate()?;
    let mut l = layout.clone();
    l.name = name.to_string();
    let stem = file_stem(name);
    std::fs::create_dir_all(user_dir).map_err(|e| anyhow!("Could not create the templates folder {}: {e}", user_dir.display()))?;
    let path = user_dir.join(format!("{stem}.json"));
    let tmp = path.with_extension("json.part");
    std::fs::write(&tmp, serde_json::to_vec_pretty(&l)?).map_err(|e| anyhow!("Could not write {}: {e}", path.display()))?;
    std::fs::rename(&tmp, &path).map_err(|e| anyhow!("Could not write {}: {e}", path.display()))?;
    Ok(info(format!("user:{stem}"), false, &l))
}

/// Delete one of the user's templates; bundled ones can't be deleted.
pub fn delete(id: &str, user_dir: &Path) -> Result<()> {
    if id.starts_with("builtin:") {
        bail!("Bundled templates can't be deleted");
    }
    let stem = id.strip_prefix("user:").filter(|s| *s == file_stem(s)).ok_or_else(|| anyhow!("There is no template '{id}'"))?;
    std::fs::remove_file(user_dir.join(format!("{stem}.json"))).map_err(|_| anyhow!("There is no template '{id}'"))
}
